import{_ as t,a as o}from"./chunks/3e0823f107b8ccf24315.DlOxo-2V.js";import{_ as a,o as i,c as n,a6 as r}from"./chunks/framework.CnPv4DE1.js";const g=JSON.parse('{"title":"The Future-Proof Skill Stack (Learn In This Order)","description":"","frontmatter":{"title":"The Future-Proof Skill Stack (Learn In This Order)","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/the-future-proof-skill-stack-learn-in-this-order.md","filePath":"en/letters/the-future-proof-skill-stack-learn-in-this-order.md"}'),s={name:"en/letters/the-future-proof-skill-stack-learn-in-this-order.md"};function l(h,e,u,p,d,c){return i(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="the-future-proof-skill-stack-learn-in-this-order" tabindex="-1">The Future-Proof Skill Stack (Learn In This Order) <a class="header-anchor" href="#the-future-proof-skill-stack-learn-in-this-order" aria-label="Permalink to &quot;The Future-Proof Skill Stack (Learn In This Order)&quot;">​</a></h1><p>Dan Koe · 2024-03-15 · <a href="https://thedankoe.com/letters/the-future-proof-skill-stack-learn-in-this-order/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/the-future-proof-skill-stack-learn-in-this-order">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/DPcw7ZA4LJA?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>I’ll be honest.</p><p>I’m worried.</p><p>I’ve gone deep into the AGI and post-labor-work rabbit hole.</p><p>There’s been a few questions on my mind for the past month:</p><ul><li>What can humans do that machines can’t?</li><li>What will the future of work look like?</li><li>What jobs – if any – will persist over the next 20 years?</li><li>What can we, as humans, do to secure an above-average future?</li></ul><p>With these problems at the forefront of my mind, I’ve found a few answers that may bring you optimism and clarity as you enter the unknown.</p><p>I want to focus on this point that many are worried about:</p><p>We don’t know what to teach children because we don’t know what will be relevant in 20 years.</p><p>I was worried about this too until I came across a <a href="https://twitter.com/Devon_Eriksen_/status/1766666283368562883" target="_blank" rel="noreferrer">post by Devon Erikson on X</a> that shines light on the issue.</p><p>I’ve been binging any podcast I can find of him and reading his new sci-fi fiction book, <a href="https://www.amazon.com/Theft-Fire-Orbital-Space-1-ebook/dp/B0CJHQ4LZN/ref=sr_1_1?crid=3C2XAP9DM9A4O&amp;dib=eyJ2IjoiMSJ9.2gMY5kigj67bbl1ijL46pAs9FPPMdUsHbnq_pBHj3GTrsFy-bQG8OIP3aSgSOR96rpiGFXTHxQLtB3QprzS9bEazs4TzU2ObKCwYEYnrl9KQVY32OwHGonpN8fXe-ImCjSWQNHta-bDuzY3ZCeBbviC87FIOI9o5bTHXEHXeBIRI6eKTR_kopf2vTRwaj91lD2xYwc2WdtZmaRYE945BKlzNrZNtcqspdbAMfRAghZc.ij2Gfs-1FqT1jP0nBxJJ8Y2QuSLkN0JNX6uO4RSHaYA&amp;dib_tag=se&amp;keywords=theft+of+fire&amp;qid=1710342205&amp;sprefix=theft+of+fi%2Caps%2C166&amp;sr=8-1" target="_blank" rel="noreferrer">Theft Of Fire</a>. He is easily becoming one of my favorite thinkers.</p><p>I hope one day, once I’ve burned through his work, I can hold a high-level conversation with him on a podcast to share the similarities and differences between our worldviews. For now, I am the student.</p><p>On to his points:</p><p><strong>Only slaves are expected to perform one task for their entire life.</strong></p><p>Our current education system reflects the education of slaves.</p><p>They were career-specific skills like growing wheat, herding sheep, and riding a horse.</p><p>Today, we are taught to be useful workers. We are taught to obey the authority. We are conditioned to get good grades out of fear of punishment.</p><p><strong>A free man is expected to act on his interests and do many things throughout his life.</strong></p><p>If you don’t create a purpose, you will be assigned one.</p><p>A purpose is a goal. Most people don’t choose their own goals.</p><p>A goal implies knowledge and skills that must be learned to solve problems that prevent you from achieving the goal.</p><p>If you don’t choose your own goal, you do not choose what you learn or what problems you solve. Your destiny is decided for you because the only potential you know is the one you were assigned.</p><p><strong>The difference between the two is how to live, how to think, and how to learn.</strong></p><p>True education, not a clone-producing machine we call public school, is an orientation toward how to live and thrive without being dependent on another.</p><p>True education does not only teach career skills that produce results by performing specific tasks, but how to think and learn so they could adapt to any situation.</p><p><strong>Stop worrying about what career skills AI will make obsolete.</strong></p><p>Worry about whether you are training (or being trained) to make ideal-future-aligned decisions, be open-minded and perceptive, and be self-motivated.</p><p>Everyone is creative.</p><p>Creativity is about achieving any goal with the knowledge and skill available to you, not fancy art or designs.</p><p>In other words, you need to learn how to set self-generated goals, utilize the internet, mentors, and the abundance of information you have access to to educate yourself.</p><p>Then, you need to embrace trial and error, self-reflect, and experiment to create your own path.</p><p>Creativity gives you the power to do whatever you want in life.</p><p>Those who don’t realize this gift are doomed to the assignments of others.</p><h2 id="the-irreplaceable-individual" tabindex="-1">The Irreplaceable Individual <a class="header-anchor" href="#the-irreplaceable-individual" aria-label="Permalink to &quot;The Irreplaceable Individual&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>It is impossible to know what the future will hold.</p><p>All we know is that there <em>will</em> be a way of life that leads to the most satisfaction.</p><p>While some aspects of this ideal lifestyle will be unique, like the interests you choose to pursue, the overarching principles of the good life remain immutable, like what allows you to pursue those interests as a sovereign individual.</p><p>To discover what these are, we must look at what <em>is not taught in schools.</em></p><p>If schools train you to be a modern slave that performs one task in one career for the entirety of your life, what is the knowledge and skill that sovereign individuals are taught – or teach themselves?</p><h3 id="_1-the-future-proof-skill-stack" tabindex="-1">1) The Future-Proof Skill Stack <a class="header-anchor" href="#_1-the-future-proof-skill-stack" aria-label="Permalink to &quot;1) The Future-Proof Skill Stack&quot;">​</a></h3><p>In Eriksen’s opinion, the seven liberal arts (or “liberating arts,” not to be confused with the ideological monstrosity found in a specific department of formal education taught by those who are not liberated themselves) are, quote:</p><ul><li><strong>Logic</strong>: how to derive truth from known facts</li><li><strong>Statistics</strong>: how to understand the implications of data</li><li><strong>Rhetoric</strong>: how to persuade, and spot persuasion tactics</li><li><strong>Research</strong>: how to gather information on an unknown subject</li><li><strong>(Practical) Psychology</strong>: how to discern and understand the true motives of others</li><li><strong>Investment</strong>: how to manage and grow existing assets</li><li><strong>Agency</strong>: how to make decisions about what course to pursue, and proactively take action to pursue it.</li></ul><p>I would encourage you to hold these in your mind while pushing into the unknown.</p><p>If you prepare yourself with a future-proof mind, what technical skills will be lucrative or useful in the far future are irrelevant because you can adapt as necessary.</p><p>To learn the liberating arts, these are the skills I learned:</p><ul><li><strong>Marketing &amp; sales</strong> – if you don’t know how to attract and persuade, you will never get what you want, and your only option will be for an employer (or the government) to give it to you. (Rhetoric, psychology)</li><li><strong>Writing &amp; thinking</strong> – the ability to communicate the value in your unique mind. The foundation of getting in front of other people. (Logic, research)</li><li><strong>Entrepreneurship</strong> – the process of taking my future into my own hands, hunting for my survival, and building products that I want to see in the world (that others care about). (Statistics, agency, investment)</li></ul><p>Some may say things like entrepreneurship aren’t a “skill,” but I would argue that any mental process that becomes more efficient with time is a skill.</p><p>Everything is a skill, but most people don’t treat their life as a practice.</p><p>Nobody can tell you how they write, think, market, and sell. They can only tell you how they do it.</p><p>Meaning that to learn these skills, you must embrace a self-experimentation mindset.</p><p>Your job is to:</p><ul><li><strong>Research processes that others have found success with.</strong> Thankfully, you can find these with a simple search.</li><li><strong>Experiment with various techniques.</strong> Implement the processes you learn and attempt to get results.</li><li><strong>Identify patterns and principles.</strong> Note the similarities between each and double down on them.</li><li><strong>Create your own process.</strong> Tailor what you learn to your unique lifestyle and situation.</li><li><strong>Contribute to true education by passing it down.</strong> Give people education that can’t be taught in schools with a fundamental grounding in critical thinking.</li></ul><p>With entrepreneurship as your vessel, you set the scene for true education and sovereignty.</p><p>With writing and thinking, you continuously create, test, and iterate on the value you have to offer.</p><p>You are required to learn practical psychology – marketing and sales – to understand the minds of yourself and your customers.</p><p>You then persuade, not force or deceive, to inspire people to care about the value you have to offer.</p><p>The future-proof skills are why I created <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a> and <a href="https://mentalmonetization.com/" target="_blank" rel="noreferrer">Mental Monetization</a> (writing + marketing and product).</p><h3 id="_2-technical-know-how" tabindex="-1">2) Technical Know-How <a class="header-anchor" href="#_2-technical-know-how" aria-label="Permalink to &quot;2) Technical Know-How&quot;">​</a></h3><p>With the foundation of a future-proof skill stack, the next step is adapting to the times with technical skills.</p><p>In the digital renaissance, this means:</p><ul><li><strong>Social media</strong> – building a name for yourself as your storefront for the value you create. The command center for your business.</li><li><strong>Content</strong> – writing or video to educate, entertain, and inspire people to see your value.</li><li><strong>Email marketing</strong> – newsletters or sequences to nurture the audience you acquire.</li><li><strong>Visual design</strong> – illustrating the vibe of your brand to spark emotion in your viewers.</li><li><strong>Funnel building</strong> – creating landing pages, websites, and fueling them with other technical skills like content and email.</li></ul><p>The requirements to learn these skills are bound to change as artificial intelligence shakes the industry. They won’t go away any time soon, but the general competition will increase due to the ease in acquiring these skills. Few people will learn the future-proof skills above, those are what will secure your future.</p><p>These technical skills are the current vessel for your entrepreneurial ventures.</p><h3 id="_3-personal-interests" tabindex="-1">3) Personal Interests <a class="header-anchor" href="#_3-personal-interests" aria-label="Permalink to &quot;3) Personal Interests&quot;">​</a></h3><p>Now the questions you’re asking are:</p><ul><li>What do I write about?</li><li>What do I market and sell?</li><li>What do I email, design, or leverage technical skills with?</li></ul><p>The interests you can’t help but tell others about.</p><p>The books you can’t pull yourself away from.</p><p>The ideas that flood your search history.</p><p>The projects you dream of building but can’t seem to find the time to.</p><p>You don’t “find” a profitable niche. You create a profitable niche through persuasion.</p><p>Nobody can tell you what niche to go into, they can only tell you the one they went into.</p><p>If you understood the future-proof skills, and therefore human nature, you would understand that you can control the perception of your interests.</p><p>Interest is generated. Interest is programmed. You are interested in specific things because of how you were raised and the information you were exposed to.</p><p>You are interested in them for a reason. That means others can <em>become</em> interested in them with well-placed writing on social media. This has happened to you before. Go scroll the timeline and tell me something doesn’t persuade you to change your behavior.</p><p>You spend time, attention, and money on your interests. That means others will spend those same resources on you if you are valuable enough.</p><p>Free people don’t choose a niche, they create one.</p><h2 id="the-digital-renaissance" tabindex="-1">The Digital Renaissance <a class="header-anchor" href="#the-digital-renaissance" aria-label="Permalink to &quot;The Digital Renaissance&quot;">​</a></h2><p><img src="'+o+'" alt=""></p><p>Most people don’t try to become the top 5% in any skill because they don’t realize that the 95% is comprised of people who put 0% effort outside of anything they were told to do by their parents or society.</p><p>30-60 minutes a day for 6-12 months puts you ahead of almost everyone.</p><p>Even that is too much to ask of most people.</p><p>Thanks to the decentralized education system being built in front of our eyes (creators on social media teaching paths they’ve gotten results in) you can quickly learn relevant skills that allow you to adapt to the changing career landscape.</p><p>In my eyes, it is silly to bank your future on education from those who are employed to be teachers.</p><p>I am not talking about general education. That is useful for getting people on the same page. I am talking about further education, when you are at the pivotal moment where you must choose what interest you want to pursue.</p><p>If the goal is to be in control of your future, it is wise to avoid education by those teaching how to be free but aren’t free themselves.</p><p>STEM education makes sense because it teaches hard skills, but an education in the liberal arts required to be free is learned better by those who have done what you are interested in doing.</p><p>Posts, podcasts, videos, courses, and coaching.</p><p>Use them to study every skill or interest we’ve discussed in this letter.</p><p>Nobody is going to give you the time. You must take it. Set aside 30-60 minutes in a non-distracting block of your day and build the habit. It will be difficult at the start as with anything new. Don’t expect otherwise.</p><h3 id="the-domain-of-mastery" tabindex="-1">The Domain Of Mastery <a class="header-anchor" href="#the-domain-of-mastery" aria-label="Permalink to &quot;The Domain Of Mastery&quot;">​</a></h3><p>Mastery is a blend of creative and specific work.</p><p>Mastery cannot be trained, it must be practiced.</p><p>You don’t succeed by being smarter.</p><p>You don’t succeed by working harder.</p><p>You succeed when you possess specific domain-relevant knowledge with a creative vessel for distribution.</p><p>I can be smart, with an IQ of 175, but if a bug occurs in a complex code base, how will being smart help me fix that? I need to know a bunch of very specific things about the code base.</p><p>Now, I can have specific knowledge of that domain, but if I am not one influencing the vision of that code base, I am not free, and I can be replaced.</p><p>It is difficult to replace someone who is highly equipped with specific knowledge, but it can still happen. And if that individual is replaced, do they have the creativity to make that knowledge work for them?</p><p>Your domain of mastery contains the skills and interests listed above.</p><ul><li><strong>Entrepreneurship is your vessel</strong> – so you are in full control of your future.</li><li><strong>Marketing and sales are your message</strong> – so you can inspire people to care about what you do.</li><li><strong>Writing and thinking are your medium</strong> – so you can distribute your message in public.</li><li><strong>Technical know-how is the “how”</strong> – so you can succeed in the current market landscape.</li><li><strong>Personal interests are the “what”</strong> – so you have a craft to pour your heart and soul into.</li><li><strong>Your ideal future is the “why”</strong> – so you solve a problem that you have experience with.</li></ul><p>An ideal future is born from adversity.</p><p>If you listen to the stories of the most successful entrepreneurs (excluding cases of unconscious competence), you will discover a common theme.</p><p>They built a product for one of three reasons:</p><ol><li>To make something that helped them better.</li><li>To solve a problem in their life.</li><li>To build what they wanted to see in the world.</li></ol><p>Or, even better, a combination of them all.</p><p>One suffered from eczema, experimented with all of the products they could on the market, and couldn’t find one that suited them.</p><p>The best they could find was a boring, scentless bar of soap.</p><p>So, they obsessed over botanicals and horticulture. Studied it like their life depended on it – because it did – and created a soap line that smelled good, looked good, and didn’t irritate their skin.</p><p>I, as another example, had trouble with consistent writing quality to fuel my business. Nobody seemed to understand that there was more to writing than just writing.</p><p>Since it was the foundation of my business success, and with having a plethora of specific knowledge in that domain, I experimented with other’s processes until I was able to create one that suited my unique goals.</p><p>That is how <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a> was born. My hyper-successful course.</p><p>It may not work for some, but for others, it is the course that changed everything and shaped a huge portion of the creator space as we know it – including many spinoff products with other processes you can try.</p><p>Notice the <a href="/letters/the-value-equation-how-to-become-a-top-1-individual-fast">Value Equation</a> from last week coming into play. It starts with a problem, reveals a goal, and sets a potential process to be created.</p><p>To wrap this up, technology only continues to advance.</p><p>Being scared of it is a great way to ruin your future.</p><p>The wise decision is to use it. Dissect it. Understand it.</p><p>Allow it to help you acquire skills faster and build your future in record time.</p><p>I hope you enjoyed this letter.</p><p>It was one of my favorites to write so far.</p><p>Dan</p>',124)])])}const y=a(s,[["render",l]]);export{g as __pageData,y as default};
